import type { ConfigContext, ExpoConfig } from 'expo/config';

/**
 * SNote mobile configuration.
 *
 * Native projects (ios/, android/) are generated by `npx expo prebuild` — never
 * edit them by hand. Widgets come from:
 *   - iOS: `targets/widget` (WidgetKit extension, via @bacons/apple-targets)
 *   - Android: `modules/snote-widgets` (App Widgets + Quick Capture activity)
 * Both share data with the app through the App Group / SharedPreferences
 * written by the `snote-widgets` native module.
 */

const BUNDLE_ID = process.env.SNOTE_BUNDLE_ID ?? 'app.snote.mobile';
export const APP_GROUP = `group.${BUNDLE_ID}`;

export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: 'SNote',
  slug: 'snote',
  scheme: 'snote',
  version: '1.0.0',
  orientation: 'portrait',
  icon: './assets/icon.png',
  userInterfaceStyle: 'automatic',
  ios: {
    bundleIdentifier: BUNDLE_ID,
    appleTeamId: process.env.APPLE_TEAM_ID,
    supportsTablet: true,
    googleServicesFile: process.env.GOOGLE_SERVICES_PLIST ?? './GoogleService-Info.plist',
    entitlements: {
      'com.apple.security.application-groups': [APP_GROUP],
    },
    infoPlist: {
      SNoteAppGroup: APP_GROUP,
      UIBackgroundModes: ['fetch', 'processing'],
      NSCameraUsageDescription: 'SNote uses the camera to add photos to your notes.',
      NSPhotoLibraryUsageDescription: 'SNote lets you add images from your library to notes.',
    },
  },
  android: {
    package: BUNDLE_ID,
    googleServicesFile: process.env.GOOGLE_SERVICES_JSON ?? './google-services.json',
    adaptiveIcon: {
      backgroundColor: '#E6F4FE',
      foregroundImage: './assets/android-icon-foreground.png',
      backgroundImage: './assets/android-icon-background.png',
      monochromeImage: './assets/android-icon-monochrome.png',
    },
    softwareKeyboardLayoutMode: 'resize',
    predictiveBackGestureEnabled: false,
  },
  web: { favicon: './assets/favicon.png' },
  plugins: [
    'expo-router',
    '@react-native-firebase/app',
    '@react-native-firebase/auth',
    [
      'expo-build-properties',
      {
        // React Native Firebase requires static frameworks on iOS.
        ios: { useFrameworks: 'static', deploymentTarget: '17.0' },
      },
    ],
    [
      '@react-native-google-signin/google-signin',
      {
        // REVERSED_CLIENT_ID from GoogleService-Info.plist.
        iosUrlScheme: process.env.GOOGLE_IOS_URL_SCHEME ?? 'com.googleusercontent.apps.REPLACE_ME',
      },
    ],
    [
      'expo-image-picker',
      {
        photosPermission: 'SNote lets you add images from your library to notes.',
        cameraPermission: 'SNote uses the camera to add photos to your notes.',
      },
    ],
    'expo-sharing',
    'expo-background-task',
    '@bacons/apple-targets',
  ],
  extra: {
    appGroup: APP_GROUP,
    // OAuth client of type "Web application" from the Firebase project (needed for the Google ID token).
    googleWebClientId: process.env.GOOGLE_WEB_CLIENT_ID ?? '',
  },
  experiments: { typedRoutes: false },
});
